/**
 * Single access point for project data:
 * src/data/works.json (hand-edited) + src/data/media.json (generated by `npm run media`).
 */
import worksData from '../data/works.json';
import mediaData from '../data/media.json';
import { categories, type CategoryId } from '../data/content';
import { filled } from './placeholder';

type Media = (typeof mediaData.works)[keyof typeof mediaData.works];

export type VideoSource =
  | { type: 'youtube'; id?: string; url?: string; owner?: 'client' | 'own' }
  | { type: 'url'; src: string; owner?: 'client' | 'own' };

export interface Work {
  slug: string;
  title: string;
  client: string;
  category: Exclude<CategoryId, 'all'>;
  categoryLabel: string;
  aspect: '16:9' | '9:16';
  views: string;
  year: string;
  featured: boolean;
  video: VideoSource;
  /** Resolved full-video target for the lightbox, or null if none provided yet. */
  full: { kind: 'youtube'; id: string; owner: 'client' | 'own' } | { kind: 'url'; src: string; owner: 'client' | 'own' } | null;
  caseStudy: { goal: string; did: string[]; results: string[] };
  media: Media | null;
}

/** Accepts a bare ID or any YouTube URL (watch, youtu.be, shorts, embed, live). */
export function youTubeId(input?: string): string | null {
  if (!input) return null;
  const s = input.trim();
  if (/^[\w-]{11}$/.test(s)) return s;
  const m = s.match(/(?:v=|youtu\.be\/|shorts\/|embed\/|live\/)([\w-]{11})/);
  return m ? m[1] : null;
}

const labelOf = (id: string) => categories.find((c) => c.id === id)?.label ?? id;

export const works: Work[] = worksData.works.map((w: any) => {
  const v = w.video ?? {};
  const owner = v.owner === 'own' ? 'own' : 'client';
  let full: Work['full'] = null;
  if (v.type === 'youtube') {
    const id = youTubeId(v.id) ?? youTubeId(v.url);
    if (id) full = { kind: 'youtube', id, owner };
  } else if (v.type === 'url' && filled(v.src)) {
    full = { kind: 'url', src: v.src, owner };
  }
  return {
    slug: w.slug,
    title: w.title,
    client: w.client ?? '',
    category: w.category,
    categoryLabel: labelOf(w.category),
    aspect: w.aspect === '9:16' ? '9:16' : '16:9',
    views: w.views ?? '',
    year: w.year ?? '',
    featured: w.featured !== false,
    video: v,
    full,
    caseStudy: { goal: '', did: [], results: [], ...(w.caseStudy ?? {}) },
    media: (mediaData.works as Record<string, Media>)[w.slug] ?? null,
  } satisfies Work;
});

export const featuredWorks = works.filter((w) => w.featured);

/** Only categories that actually have work, plus "All". */
export const usedCategories = (list: Work[]) =>
  categories.filter((c) => c.id === 'all' || list.some((w) => w.category === c.id));
